def find_increasing_sequence(n, b):
    from itertools import permutations

    def is_increasing(b_perm):
        a = [b_perm[0]]
        for i in range(1, n):
            a.append(a[-1] ^ b_perm[i])
        return all(a[i] < a[i + 1] for i in range(n - 1))

    for perm in permutations(b):
        if is_increasing(list(perm)):
            return "Yes", perm
    return "No", []

